import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CFOYCmPM.js";const g=JSON.parse('{"title":"Chapter 9: Troubleshooting & FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md","lastUpdated":null}'),s={name:"guide/troubleshooting.md"};function i(n,e,l,u,d,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="chapter-9-troubleshooting-faq" tabindex="-1">Chapter 9: Troubleshooting &amp; FAQ <a class="header-anchor" href="#chapter-9-troubleshooting-faq" aria-label="Permalink to &quot;Chapter 9: Troubleshooting &amp; FAQ&quot;">​</a></h1><p>Quick solutions for common beginner questions and setup issues.</p><hr><h2 id="🛠️-common-issues-fixes" tabindex="-1">🛠️ Common Issues &amp; Fixes <a class="header-anchor" href="#🛠️-common-issues-fixes" aria-label="Permalink to &quot;🛠️ Common Issues &amp; Fixes&quot;">​</a></h2><h3 id="could-not-start-the-studio-server" tabindex="-1">&quot;Could not start the studio server&quot; <a class="header-anchor" href="#could-not-start-the-studio-server" aria-label="Permalink to &quot;&quot;Could not start the studio server&quot;&quot;">​</a></h3><ul><li><strong>Cause:</strong> Port <code>8765</code> is occupied by another local background web service.</li><li><strong>Fix:</strong> Close conflicting background applications or open Windows Task Manager and end any leftover <code>python.exe</code> processes.</li></ul><h3 id="black-2d-map-no-terrain-data-yet" tabindex="-1">Black 2D Map / &quot;No terrain data yet&quot; <a class="header-anchor" href="#black-2d-map-no-terrain-data-yet" aria-label="Permalink to &quot;Black 2D Map / &quot;No terrain data yet&quot;&quot;">​</a></h3><ul><li><strong>Cause:</strong> Satellite imagery has not been extracted yet.</li><li><strong>Fix:</strong> Switch to the <strong>Map</strong> tab (<code>Alt + 1</code>). In the right panel, click <strong>⬇ Extract … imagery from DayZ</strong>.</li></ul><h3 id="capture-buttons-are-greyed-out" tabindex="-1">Capture buttons are greyed out <a class="header-anchor" href="#capture-buttons-are-greyed-out" aria-label="Permalink to &quot;Capture buttons are greyed out&quot;">​</a></h3><ul><li><strong>Cause:</strong> DayZ was not found in registered Steam library folders.</li><li><strong>Fix:</strong> Ensure DayZ is installed through Steam. If DayZ is installed on a secondary drive, verify that drive is added in Steam under <strong>Settings ▸ Storage</strong>.</li></ul><h3 id="mod-exported-but-shows-not-signed" tabindex="-1">Mod exported but shows &quot;Not signed&quot; <a class="header-anchor" href="#mod-exported-but-shows-not-signed" aria-label="Permalink to &quot;Mod exported but shows &quot;Not signed&quot;&quot;">​</a></h3><ul><li><strong>Cause:</strong> DayZ Tools is either missing or has never been initialized.</li><li><strong>Fix:</strong> Install <strong>DayZ Tools</strong> from Steam (<strong>Library ▸ Tools ▸ DayZ Tools</strong>). Launch DayZ Tools at least once so it writes its paths to the Windows registry, then export again.</li></ul><h3 id="kicked-from-local-test-server-game-restart-required" tabindex="-1">Kicked from local test server: &quot;Game restart required&quot; <a class="header-anchor" href="#kicked-from-local-test-server-game-restart-required" aria-label="Permalink to &quot;Kicked from local test server: &quot;Game restart required&quot;&quot;">​</a></h3><ul><li><strong>Cause:</strong> Dedicated servers enforce BattlEye security.</li><li><strong>Fix:</strong> Do not launch DayZ manually; use DayZ Studio&#39;s <strong>② Join with the game</strong> button, which correctly initializes BattlEye.</li></ul><h3 id="windows-smartscreen-windows-protected-your-pc" tabindex="-1">Windows SmartScreen: &quot;Windows protected your PC&quot; <a class="header-anchor" href="#windows-smartscreen-windows-protected-your-pc" aria-label="Permalink to &quot;Windows SmartScreen: &quot;Windows protected your PC&quot;&quot;">​</a></h3><ul><li><strong>Cause:</strong> DayZ Studio is an independent alpha release without an expensive EV enterprise code-signing certificate.</li><li><strong>Fix:</strong> Click <strong>More info</strong>, then click <strong>Run anyway</strong>.</li></ul><hr><h2 id="🐞-built-in-bug-reporter" tabindex="-1">🐞 Built-in Bug Reporter <a class="header-anchor" href="#🐞-built-in-bug-reporter" aria-label="Permalink to &quot;🐞 Built-in Bug Reporter&quot;">​</a></h2><p>If you encounter unexpected behavior:</p><ol><li>Go to <strong>File ▸ 🐞 Report a bug…</strong></li><li>Describe what happened and click <strong>Open GitHub issue</strong>.</li><li>Studio zips its application log, recent editor errors, and the latest DayZ logs into <code>Documents\\DayZStudio\\BugReports</code>.</li><li>It opens a pre-filled GitHub issue in your browser and displays the bug report folder. Simply drag the <code>.zip</code> file into GitHub and click submit!</li></ol>',20)])])}const p=t(s,[["render",i]]);export{g as __pageData,p as default};
